def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        table = {}
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = False
        tx_conn = None
        tx_snapshot_table = None
        tx_snapshot_main_changes = 0
        tx_snapshot_other_changes = 0
        tx_snapshot_main_total = 0
        tx_snapshot_other_total = 0

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            key = action.get("key")
            value = action.get("value")

            if op == "begin":
                if not in_tx:
                    in_tx = True
                    tx_conn = conn
                    tx_snapshot_table = dict(table)
                    tx_snapshot_main_changes = main_changes
                    tx_snapshot_other_changes = other_changes
                    tx_snapshot_main_total = main_total
                    tx_snapshot_other_total = other_total
            elif op == "commit":
                if in_tx:
                    in_tx = False
                    tx_conn = None
            elif op == "rollback":
                if in_tx:
                    table = tx_snapshot_table
                    main_changes = tx_snapshot_main_changes
                    other_changes = tx_snapshot_other_changes
                    main_total = tx_snapshot_main_total
                    other_total = tx_snapshot_other_total
                    in_tx = False
                    tx_conn = None
            else:
                changed = 0
                if op == "put":
                    if key in table:
                        if put_mode == "ignore":
                            changed = 0
                        elif put_mode == "replace":
                            table[key] = value
                            changed = 1
                        else: # upsert
                            table[key] = value
                            changed = 1
                    else:
                        table[key] = value
                        changed = 1
                elif op == "update":
                    if key in table:
                        table[key] = value
                        changed = 1
                elif op == "delete":
                    if key in table:
                        del table[key]
                        changed = 1

                if conn == "main":
                    main_changes = changed
                    main_total += changed
                else:
                    other_changes = changed
                    other_total += changed

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total":
            channel = main_total
        else: # both
            channel = main_total + other_total

        return channel, len(table), sum(table.values())

    def consistent(put_mode, trigger, channel_mode):
        for receipt in history:
            actions = receipt.get("actions", [])
            observed = receipt.get("observed", {})
            ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
            if ch != observed.get("channel"):
                return False
            if cc != observed.get("committed_count"):
                return False
            if cs != observed.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("changes", "total", "both"):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cc)
        elif goal == "committed_sum":
            values.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}
